--
-- Acionadores `tbitenscesta`
--
DELIMITER $$
CREATE TRIGGER `trg_Estorno_Delete_Cesta` AFTER DELETE ON `tbitenscesta` FOR EACH ROW BEGIN
    UPDATE tbEstoqueItens
    SET quantidade = quantidade + OLD.quantidade
    WHERE codList = OLD.codList;
END
$$
DELIMITER ;

