--
-- Acionadores `tblista`
--
DELIMITER $$
CREATE TRIGGER `trg_CriarRegistroEstoque` AFTER INSERT ON `tblista` FOR EACH ROW BEGIN
    INSERT INTO tbEstoqueItens (codList, quantidade, dataMovimentacao, horaMovimentacao)
    VALUES (NEW.codList, 0, CURDATE(), CURTIME());
END
$$
DELIMITER ;

