--
-- Acionadores `tbmovimentacoes`
--
DELIMITER $$
CREATE TRIGGER `trg_valida_saida` BEFORE INSERT ON `tbmovimentacoes` FOR EACH ROW BEGIN
    DECLARE saldo INT;

    SELECT COALESCE(SUM(quantidade),0)
    INTO saldo
    FROM tbMovimentacoes
    WHERE codList = NEW.codList;

    IF NEW.tipoMovimentacao = 'SAIDA' AND saldo + NEW.quantidade < 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Estoque insuficiente';
    END IF;
END
$$
DELIMITER ;

