-- Estrutura para tabela `tbprodutos_backup`
--

CREATE TABLE `tbprodutos_backup` (
  `codProd` int(11) NOT NULL DEFAULT 0,
  `descricao` varchar(100) NOT NULL,
  `quantidade` int(11) NOT NULL,
  `peso` decimal(10,3) NOT NULL,
  `unidade` varchar(20) NOT NULL,
  `codBar` varchar(13) DEFAULT NULL,
  `dataDeEntrada` datetime NOT NULL,
  `dataDeValidade` date NOT NULL,
  `dataLimiteDeSaida` date NOT NULL,
  `tipoMovimentacao` varchar(20) DEFAULT 'ENTRADA',
  `codUsu` int(11) NOT NULL,
  `codOri` int(11) NOT NULL,
  `codList` int(11) NOT NULL,
  `observacao` varchar(500) DEFAULT NULL,
  `destino` varchar(200) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

