--
-- Estrutura stand-in para view `vwestoqueatual`
-- (Veja abaixo para a visão atual)
--
CREATE TABLE `vwestoqueatual` (
`codList` int(11)
,`descricao` varchar(100)
,`unidade` varchar(20)
,`peso` int(11)
,`saldo` decimal(32,0)
);

-- --------------------------------------------------------

--
-- Estrutura para view `vwestoqueatual`
--
DROP TABLE IF EXISTS `vwestoqueatual`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vwestoqueatual`  AS SELECT `l`.`codList` AS `codList`, `l`.`descricao` AS `descricao`, `l`.`unidade` AS `unidade`, `l`.`peso` AS `peso`, coalesce(sum(`m`.`quantidade`),0) AS `saldo` FROM (`tblista` `l` left join `tbmovimentacoes` `m` on(`m`.`codList` = `l`.`codList`)) GROUP BY `l`.`codList`, `l`.`descricao`, `l`.`unidade`, `l`.`peso` ;

